namespace forkmesh::ui::ChromeDotGrid {

QFont captionFont()
{
    static const QFont font = [] {
        QFont f = QGuiApplication::font();
        f.setWeight(QFont::Normal);
        f.setPixelSize(8); // as small as the caption can go and still read
        return f;
    }();
    return font;
}

int captionHeight()
{
    static const int height = QFontMetrics(captionFont()).height() + 3;
    return height;
}

int captionWidth(const QString &text)
{
    return QFontMetrics(captionFont()).horizontalAdvance(text);
}

int totalHeight()
{ return kGridHeight + captionHeight(); }

void paintCaption(QPainter &p, const QWidget *widget,
                         const QString &text)
{
    QColor ink = widget->palette().color(QPalette::WindowText);
    ink.setAlpha(170);
    p.save();
    p.setPen(ink);
    p.setFont(captionFont());
    p.drawText(QRect(0, kGridHeight, widget->width(), captionHeight()),
               Qt::AlignLeft | Qt::AlignVCenter, text);
    p.restore();
}

int widthFor(int columns, const QString &caption)
{
    return columns <= 0 ? 0 : qMax(columns * kPitch, captionWidth(caption));
}

QTimer *animationClock()
{
    static QPointer<QTimer> clock;
    if (!clock) {
        clock = new QTimer(QCoreApplication::instance());
        clock->setInterval(kAnimationIntervalMs);
    }
    return clock;
}

void holdAnimationClock(bool *held, bool want)
{
    static int holders = 0;
    if (!held || *held == want)
        return;
    *held = want;
    holders = qMax(0, holders + (want ? 1 : -1));
    if (!QCoreApplication::instance())
        return;
    QTimer *clock = animationClock();
    if (holders > 0 && !clock->isActive())
        clock->start();
    else if (holders == 0 && clock->isActive())
        clock->stop();
}

} // namespace forkmesh::ui::ChromeDotGrid

