void blankSelectionBand(QAbstractItemView *view)
{
    const QString name = view->objectName();
    if (name.isEmpty())
        return; // no object-name rule to override
    const QString sel = QStringLiteral("#") + name;
    view->setStyleSheet(Theme::remapSheet(
        view->styleSheet() + sel +
        QStringLiteral(" { selection-background-color: transparent; ") +
        QStringLiteral("selection-color: palette(text); }") + sel +
        QStringLiteral("::item:selected { background: transparent; ") +
        QStringLiteral("color: palette(text); }")));
}

void enableHoverRowHighlight(QAbstractItemView *view)
{
    if (!view)
        return;
    view->setItemDelegate(new HoverRowDelegate(view));
    blankSelectionBand(view);
}

void paintRowBorder(QPainter *painter,
                           const QStyleOptionViewItem &option,
                           const QModelIndex &index, const QColor &color)
{
    bool drawLeft = index.column() == 0;
    bool drawRight = true;
    if (const auto *table = qobject_cast<const QTableView *>(option.widget)) {
        QHeaderView *header = table->horizontalHeader();
        int first = -1, last = -1;
        for (int v = 0; v < header->count(); ++v) {
            if (header->isSectionHidden(header->logicalIndex(v)))
                continue;
            if (first < 0)
                first = v;
            last = v;
        }
        const int visual = header->visualIndex(index.column());
        drawLeft = (visual == first);
        drawRight = (visual == last);
    }
    const QRect r = option.rect;
    painter->save();
    painter->setRenderHint(QPainter::Antialiasing, false);
    painter->setPen(QPen(color, 1));
    painter->drawLine(r.topLeft(), r.topRight());
    painter->drawLine(QPoint(r.left(), r.bottom()), QPoint(r.right(), r.bottom()));
    if (drawLeft)
        painter->drawLine(r.topLeft(), QPoint(r.left(), r.bottom()));
    if (drawRight)
        painter->drawLine(QPoint(r.right(), r.top()), QPoint(r.right(), r.bottom()));
    painter->restore();
}

void paintRowSelectionBorder(QPainter *painter,
                                    const QStyleOptionViewItem &option,
                                    const QModelIndex &index)
{
    if (!(option.state & QStyle::State_Selected))
        return;
    paintRowBorder(painter, option, index,
                   nextAccentTint(QColor(46, 160, 67)));
}

void makeColumnsResizable(QTableWidget *table,
                                 const QSet<int> &keepFlexibleColumns)
{
    if (!table || !table->model())
        return;
    QHeaderView *header = table->horizontalHeader();
    auto done = std::make_shared<bool>(false);
    QObject::connect(
        table->model(), &QAbstractItemModel::rowsInserted, table,
        [table, header, done, keepFlexibleColumns]() {
            if (*done)
                return;
            *done = true;
            QTimer::singleShot(0, table, [table, header, keepFlexibleColumns]() {
                // growColumnsToContents() listens for manual section resizes.
                // Keep this initial automatic fit from being mistaken for one.
                header->setProperty("fmAutoSizingColumns", true);
                const bool stretchLast = header->stretchLastSection();
                const int last = header->count() - 1;
                header->setStretchLastSection(false);
                for (int i = 0; i < header->count(); ++i) {
                    if (keepFlexibleColumns.contains(i))
                        continue; // stays Stretch, absorbing the spare width
                    const QHeaderView::ResizeMode mode = header->sectionResizeMode(i);
                    const bool autosized =
                        mode == QHeaderView::ResizeToContents ||
                        mode == QHeaderView::Stretch || (stretchLast && i == last);
                    if (!autosized)
                        continue; // leave Fixed button columns untouched
                    header->setSectionResizeMode(i, QHeaderView::Interactive);
                    table->resizeColumnToContents(i);
                }
                header->setProperty("fmAutoSizingColumns", false);
            });
        });
}

void makeColumnsResizable(QTableWidget *table, int keepFlexibleColumn)
{
    makeColumnsResizable(table, keepFlexibleColumn >= 0
                                    ? QSet<int>{keepFlexibleColumn}
                                    : QSet<int>{});
}

void growColumnsToContents(QTableWidget *table, int maxSectionWidth)
{
    if (!table || !table->model() || table->rowCount() <= 0)
        return;
    QHeaderView *header = table->horizontalHeader();
    if (!header->property("fmTracksColumnDrags").toBool()) {
        header->setProperty("fmTracksColumnDrags", true);
        QObject::connect(
            header, &QHeaderView::sectionResized, header,
            [header](int logical, int oldSize, int newSize) {
                // Our own widening below, and the header menu hiding or
                // restoring a column, both arrive here too; neither is the
                // user setting a width they want kept.
                if (header->property("fmAutoSizingColumns").toBool() ||
                    header->property("fmGrowingColumns").toBool() ||
                    oldSize <= 0 || newSize <= 0)
                    return;
                QVariantList sized =
                    header->property("fmUserSizedColumns").toList();
                if (!sized.contains(logical)) {
                    sized.append(logical);
                    header->setProperty("fmUserSizedColumns", sized);
                }
            });
    }
    const QVariantList userSized =
        header->property("fmUserSizedColumns").toList();
    header->setProperty("fmGrowingColumns", true);
    for (int column = 0; column < header->count(); ++column) {
        // Interactive is what makeColumnsResizable() leaves behind. Anything
        // still auto-sized re-measures itself, and anything Fixed was given its
        // width by hand.
        if (header->sectionResizeMode(column) != QHeaderView::Interactive ||
            header->isSectionHidden(column) || userSized.contains(column))
            continue;
        const int current = header->sectionSize(column);
        // QTableView keeps sizeHintForColumn() protected. Temporarily use its
        // public content-fit operation to obtain the same measurement, then
        // restore the larger of the old and newly required widths.
        table->resizeColumnToContents(column);
        const int fits = qMin(qMax(header->sectionSize(column),
                                   header->sectionSizeHint(column)),
                              maxSectionWidth);
        header->resizeSection(column, qMax(current, fits));
    }
    header->setProperty("fmGrowingColumns", false);
}

int progressPctForX(const QRect &cellRect, int x, const QFontMetrics &fm)
{
    const QRect cell = cellRect.adjusted(8, 0, -8, 0);
    const int textW = fm.horizontalAdvance(QStringLiteral("100%")) + 4;
    const int barW = qMax(1, cell.width() - textW);
    return qBound(0, qRound((x - cell.left()) * 100.0 / barW), 100);
}

void paintProgressBar(QPainter *painter, const QRect &cellRect, int pct,
                             const QFontMetrics &fm)
{
    pct = qBound(0, pct, 100);
    const QRect cell = cellRect.adjusted(8, 0, -8, 0);
    const QString label = QStringLiteral("%1%").arg(pct);
    const int textW = fm.horizontalAdvance(QStringLiteral("100%")) + 4;
    QRect barRect(cell.left(), cell.center().y() - 4,
                  qMax(0, cell.width() - textW), 8);
    QRect textRect(barRect.right() + 4, cell.top(), textW, cell.height());

    const bool dark = currentThemeIsDark();
    const QColor track = Theme::remapColor(QColor(dark ? "#30363d" : "#d0d7de"));
    const QColor fillColor(pct >= 100 ? "#3fb950" : "#388bfd"); // green / blue
    const QColor textColor = Theme::remapColor(QColor(dark ? "#8b949e" : "#57606a"));

    painter->save();
    painter->setRenderHint(QPainter::Antialiasing, true);
    painter->setPen(Qt::NoPen);
    painter->setBrush(track);
    painter->drawRoundedRect(barRect, 4, 4);
    if (pct > 0) {
        QRect fill(barRect.left(), barRect.top(),
                   qMax(barRect.height(), barRect.width() * pct / 100),
                   barRect.height());
        painter->setBrush(fillColor);
        painter->drawRoundedRect(fill, 4, 4);
    }
    painter->setPen(textColor);
    painter->drawText(textRect, Qt::AlignVCenter | Qt::AlignRight, label);
    painter->restore();
}

void paintResourceBar(QPainter *painter, const QRect &cellRect, int pct,
                             const QFontMetrics &fm)
{
    const bool dark = currentThemeIsDark();
    const QColor track = Theme::remapColor(QColor(dark ? "#30363d" : "#d0d7de"));
    const QColor textColor = Theme::remapColor(QColor(dark ? "#8b949e" : "#57606a"));
    const QRect cell = cellRect.adjusted(8, 0, -8, 0);

    if (pct < 0) {
        painter->save();
        painter->setPen(textColor);
        painter->drawText(cell, Qt::AlignVCenter | Qt::AlignLeft,
                          QString::fromUtf8("\xE2\x80\x94"));
        painter->restore();
        return;
    }
    pct = qBound(0, pct, 100);
    const QString label = QStringLiteral("%1%").arg(pct);
    const int textW = fm.horizontalAdvance(QStringLiteral("100%")) + 4;
    QRect barRect(cell.left(), cell.center().y() - 4,
                  qMax(0, cell.width() - textW), 8);
    QRect textRect(barRect.right() + 4, cell.top(), textW, cell.height());

    const QColor fillColor(pct >= 90 ? "#f85149" : (pct >= 70 ? "#d29922" : "#3fb950"));

    painter->save();
    painter->setRenderHint(QPainter::Antialiasing, true);
    painter->setPen(Qt::NoPen);
    painter->setBrush(track);
    painter->drawRoundedRect(barRect, 4, 4);
    if (pct > 0) {
        QRect fill(barRect.left(), barRect.top(),
                   qMax(barRect.height(), barRect.width() * pct / 100),
                   barRect.height());
        painter->setBrush(fillColor);
        painter->drawRoundedRect(fill, 4, 4);
    }
    painter->setPen(textColor);
    painter->drawText(textRect, Qt::AlignVCenter | Qt::AlignRight, label);
    painter->restore();
}

QString formatByteSize(qint64 bytes)
{
    static const char *units[] = {"B", "KB", "MB", "GB", "TB"};
    double size = bytes;
    int unit = 0;
    while (size >= 1024.0 && unit < 4) {
        size /= 1024.0;
        ++unit;
    }
    return unit == 0 ? QStringLiteral("%1 B").arg(bytes)
                     : QStringLiteral("%1 %2").arg(size, 0, 'f', 1).arg(units[unit]);
}

SortTableWidgetItem *makeResourceBarCell(int pct, const QString &tooltip)
{
    auto *item = new SortTableWidgetItem(QString());
    item->setData(kProgressBarRole, pct);
    item->setData(kTableSortRole, double(pct)); // unknown (-1) sorts below 0%
    if (!tooltip.isEmpty())
        item->setToolTip(tooltip);
    return item;
}

SortTableWidgetItem *makeByteUsageCell(const QString &label, qint64 used, qint64 total)
{
    if (total <= 0)
        return makeResourceBarCell(-1, QString());
    used = qBound<qint64>(0, used, total);
    const int pct = int(qRound(100.0 * double(used) / double(total)));
    const QString tip =
        QString::fromUtf8("%1: %2 used of %3 (%4%) \xC2\xB7 %5 free")
            .arg(label, formatByteSize(used), formatByteSize(total))
            .arg(pct)
            .arg(formatByteSize(total - used));
    return makeResourceBarCell(pct, tip);
}

QString nodeHealthColor(int severity)
{
    switch (severity) {
    case NodeDiagnostics::Critical:
        return QStringLiteral("#f85149");
    case NodeDiagnostics::Warning:
        return QStringLiteral("#d29922");
    case NodeDiagnostics::Info:
        return QStringLiteral("#58a6ff");
    default:
        return QStringLiteral("#3fb950"); // all clear
    }
}

SortTableWidgetItem *makeNodeHealthCell(
    const QList<NodeDiagnostics::Finding> &findings, qint64 diagnosticsMs,
    qint64 nowMs)
{
    const bool reported = diagnosticsMs > 0;
    auto *item = new SortTableWidgetItem(
        NodeDiagnostics::summaryLabel(findings, reported));
    const int severity =
        reported ? NodeDiagnostics::worstSeverity(findings) : -1;
    item->setData(kTableSortRole, double(severity));
    if (!reported) {
        item->setToolTip(QStringLiteral(
            "This node has not reported a self-check — an older build, or "
            "self-diagnostics turned off in its settings."));
        return item;
    }
    item->setForeground(QColor(nodeHealthColor(severity)));
    QString tip = findings.isEmpty()
                      ? QStringLiteral("Self-check found no problems.")
                      : NodeDiagnostics::detailText(findings);
    const qint64 ageMs = nowMs > 0 ? nowMs - diagnosticsMs : 0;
    if (ageMs > 60 * 1000)
        tip += QStringLiteral("\n\nLast reported %1 min ago")
                   .arg(ageMs / (60 * 1000));
    item->setToolTip(tip);
    return item;
}

SortTableWidgetItem *makeCpuUsageCell(double cpuPercent)
{
    if (cpuPercent < 0.0)
        return makeResourceBarCell(-1, QString());
    const int pct = int(qRound(qBound(0.0, cpuPercent, 100.0)));
    return makeResourceBarCell(
        pct, QStringLiteral("CPU: %1% busy across all cores").arg(pct));
}

