QString actionAlertMode()
{
    QSettings settings;
    const QString mode = settings.value(kActionAlertModeSetting).toString();
    if (mode == QLatin1String("all") || mode == QLatin1String("failed") ||
        mode == QLatin1String("none"))
        return mode;
    return settings.value(kActionAlertSetting, false).toBool()
               ? QStringLiteral("all")
               : QStringLiteral("none");
}

namespace {

QString actionPingEventKey(ActionPingEvent event)
{
    switch (event) {
    case ActionPingEvent::Started:
        return QStringLiteral("started");
    case ActionPingEvent::Succeeded:
        return QStringLiteral("succeeded");
    case ActionPingEvent::Failed:
        return QStringLiteral("failed");
    case ActionPingEvent::Stopped:
        return QStringLiteral("stopped");
    case ActionPingEvent::Approval:
        return QStringLiteral("approval");
    }
    return QString();
}

} // namespace

QString actionPingEventLabel(ActionPingEvent event)
{
    switch (event) {
    case ActionPingEvent::Started:
        return QStringLiteral("Run started");
    case ActionPingEvent::Succeeded:
        return QStringLiteral("Run succeeded");
    case ActionPingEvent::Failed:
        return QStringLiteral("Run failed");
    case ActionPingEvent::Stopped:
        return QStringLiteral("Run stopped");
    case ActionPingEvent::Approval:
        return QStringLiteral("Run waiting for approval");
    }
    return QString();
}

bool actionPingEnabled(ActionPingEvent event)
{
    const bool routine = event == ActionPingEvent::Started ||
                         event == ActionPingEvent::Succeeded;
    return QSettings()
        .value(QStringLiteral("actions/ping/") + actionPingEventKey(event),
               !routine)
        .toBool();
}

void setActionPingEnabled(ActionPingEvent event, bool enabled)
{
    QSettings().setValue(
        QStringLiteral("actions/ping/") + actionPingEventKey(event), enabled);
}

bool actionPopupEnabled(ActionPingEvent event)
{
    QSettings settings;
    const QString key =
        QStringLiteral("actions/popup/") + actionPingEventKey(event);
    if (settings.contains(key))
        return settings.value(key).toBool();
    const QString mode = actionAlertMode();
    switch (event) {
    case ActionPingEvent::Started:
        return mode != QLatin1String("none") &&
               settings.value(kActionAlertStartedSetting, false).toBool();
    case ActionPingEvent::Succeeded:
        return mode == QLatin1String("all");
    case ActionPingEvent::Failed:
        return mode != QLatin1String("none");
    case ActionPingEvent::Stopped:
    case ActionPingEvent::Approval:
        return false;
    }
    return false;
}

void setActionPopupEnabled(ActionPingEvent event, bool enabled)
{
    QSettings().setValue(
        QStringLiteral("actions/popup/") + actionPingEventKey(event), enabled);
}

