qint64 pingPauseUntilMs()
{
    const qint64 until =
        QSettings().value(kPingPauseUntilSetting, 0).toLongLong();
    // A deadline already past is a pause that ended, which every surface
    // renders the same as never having set one.
    return until > QDateTime::currentMSecsSinceEpoch() ? until : 0;
}

bool pingsPaused()
{
    return pingPauseUntilMs() > 0 || forkmesh::pings::quietUntilMs() > 0;
}

QString pingPauseLabel(qint64 untilMs)
{
    if (untilMs <= 0)
        return QStringLiteral("Notifications are on");
    const QDateTime deadline = QDateTime::fromMSecsSinceEpoch(untilMs);
    const QString time = QLocale().toString(deadline.time(), QLocale::ShortFormat);
    if (deadline.date() == QDate::currentDate())
        return QStringLiteral("Notifications paused until %1").arg(time);
    return QStringLiteral("Notifications paused until %1, %2")
        .arg(deadline.date().toString(QStringLiteral("ddd d MMM")), time);
}

