bool requestFirewallCanPrompt()
{
    return !QGuiApplication::platformName().contains(
        QStringLiteral("offscreen"), Qt::CaseInsensitive);
}

QList<BackoffNetworkAccessManager::FirewallRuleEntry>
defaultApprovedFirewallRules()
{
    static const QList<BackoffNetworkAccessManager::FirewallRuleEntry> rules = [] {
        QFile file(kDefaultApprovedFirewallRulesResource);
        if (!file.open(QIODevice::ReadOnly))
            return QList<BackoffNetworkAccessManager::FirewallRuleEntry>();
        return BackoffNetworkAccessManager::parseFirewallRuleList(file.readAll());
    }();
    return rules;
}

void seedDefaultApprovedFirewallRules(QSettings &settings, QStringList *rules)
{
    QStringList seeded =
        settings.value(kRequestFirewallSeededDefaultsSetting).toStringList();
    const QStringList denied =
        settings.value(kRequestFirewallDenylistSetting).toStringList();
    bool changed = false;
    for (const BackoffNetworkAccessManager::FirewallRuleEntry &entry :
         defaultApprovedFirewallRules()) {
        if (seeded.contains(entry.rule))
            continue;
        seeded.append(entry.rule);
        changed = true;
        if (!denied.contains(entry.rule) && !rules->contains(entry.rule))
            rules->append(entry.rule);
    }
    if (!changed)
        return;
    rules->sort(Qt::CaseInsensitive);
    settings.setValue(kRequestFirewallWhitelistSetting, *rules);
    settings.setValue(kRequestFirewallSeededDefaultsSetting, seeded);
}

QStringList requestFirewallWhitelist()
{
    QSettings settings;
    QStringList rules = settings.value(kRequestFirewallWhitelistSetting).toStringList();
    if (!requestFirewallCanPrompt()) {
        if (!settings.value(kRequestFirewallDefaultSeededSetting, false).toBool()) {
            for (const QString &rule : defaultRequestFirewallWhitelist()) {
                if (!rules.contains(rule))
                    rules.append(rule);
            }
            rules.sort(Qt::CaseInsensitive);
            settings.setValue(kRequestFirewallWhitelistSetting, rules);
            settings.setValue(kRequestFirewallDefaultSeededSetting, true);
        }
        seedDefaultApprovedFirewallRules(settings, &rules);
        return rules;
    }
    if (!settings.value(kRequestFirewallBuiltinApprovalsRevokedSetting, false)
             .toBool()) {
        // Installs from before carry the seeded rules nobody chose. Take them
        // out once; the next request to each asks like any other destination.
        if (settings.value(kRequestFirewallDefaultSeededSetting, false).toBool()) {
            for (const QString &rule : defaultRequestFirewallWhitelist())
                rules.removeAll(rule);
            settings.setValue(kRequestFirewallWhitelistSetting, rules);
        }
        settings.setValue(kRequestFirewallBuiltinApprovalsRevokedSetting, true);
    }
    seedDefaultApprovedFirewallRules(settings, &rules);
    return rules;
}

