QString formatUsageCredits(double minorUnits, const QString &currency)
{
    const QString code = currency.trimmed().isEmpty()
                             ? QStringLiteral("USD")
                             : currency.trimmed().toUpper();
    const QString amount = QString::number(minorUnits / 100.0, 'f', 2);
    if (code == QLatin1String("USD"))
        return QLatin1Char('$') + amount;
    if (code == QLatin1String("EUR"))
        return QString::fromUtf8("\xE2\x82\xAC") + amount;
    if (code == QLatin1String("GBP"))
        return QString::fromUtf8("\xC2\xA3") + amount;
    return amount + QLatin1Char(' ') + code;
}

