QMutex &agentAccountProfileCacheMutex()
{
    static QMutex mutex;
    return mutex;
}

QHash<QString, QList<AgentAccountProfile>> &agentAccountProfileCache()
{
    static QHash<QString, QList<AgentAccountProfile>> cache;
    return cache;
}

QHash<QString, QString> &activeAgentAccountIdCache()
{
    static QHash<QString, QString> cache;
    return cache;
}

void invalidateAgentAccountProfileCache()
{
    QMutexLocker locker(&agentAccountProfileCacheMutex());
    agentAccountProfileCache().clear();
    activeAgentAccountIdCache().clear();
}

QList<AgentAccountProfile> agentAccountProfilesUncached(
    const QString &provider)
{
    QSettings settings;
    const QString defaultLabel =
        settings.value(agentAccountLabelSetting(provider, QStringLiteral("default")),
                       QStringLiteral("Default account"))
            .toString()
            .trimmed();
    QList<AgentAccountProfile> profiles{
        {QStringLiteral("default"),
         defaultLabel.isEmpty() ? QStringLiteral("Default account") : defaultLabel,
         agentAccountDefaultConfigDir(provider), true}};
    settings.beginGroup(agentAccountProfilesGroup(provider));
    const QStringList ids = settings.childGroups();
    for (const QString &id : ids) {
        settings.beginGroup(id);
        const QString dir = settings.value(QStringLiteral("configDir")).toString();
        if (!dir.trimmed().isEmpty()) {
            profiles.append({id,
                             settings.value(QStringLiteral("label"),
                                            QStringLiteral("Account"))
                                 .toString(),
                             dir, false});
        }
        settings.endGroup();
    }
    settings.endGroup();
    return profiles;
}

QList<AgentAccountProfile> agentAccountProfiles(const QString &provider)
{
    {
        QMutexLocker locker(&agentAccountProfileCacheMutex());
        const auto cached = agentAccountProfileCache().constFind(provider);
        if (cached != agentAccountProfileCache().cend())
            return *cached;
    }
    const QList<AgentAccountProfile> profiles =
        agentAccountProfilesUncached(provider);
    QMutexLocker locker(&agentAccountProfileCacheMutex());
    agentAccountProfileCache().insert(provider, profiles);
    return profiles;
}

AgentAccountProfile activeAgentAccount(const QString &provider)
{
    const QList<AgentAccountProfile> profiles = agentAccountProfiles(provider);
    QString selected;
    {
        QMutexLocker locker(&agentAccountProfileCacheMutex());
        const auto cached = activeAgentAccountIdCache().constFind(provider);
        if (cached != activeAgentAccountIdCache().cend())
            selected = *cached;
    }
    if (selected.isNull()) {
        selected = QSettings()
                       .value(agentActiveAccountSetting(provider),
                              QStringLiteral("default"))
                       .toString();
        QMutexLocker locker(&agentAccountProfileCacheMutex());
        activeAgentAccountIdCache().insert(provider, selected);
    }
    for (const AgentAccountProfile &profile : profiles)
        if (profile.id == selected)
            return profile;
    return profiles.first();
}

