bool gitOutput(const QString &clientDir, const QStringList &arguments, QString *out)
{
    QProcess process;
    process.setWorkingDirectory(clientDir);
    process.start(QStringLiteral("git"), arguments);
    if (!process.waitForFinished(3000)) {
        process.kill();
        process.waitForFinished(1000);
        return false;
    }
    if (process.exitCode() != 0)
        return false;
    if (out)
        *out = QString::fromUtf8(process.readAllStandardOutput()).trimmed();
    return true;
}

QStringList quickUpdatePullArguments(const QString &clientDir)
{
    QString upstream;
    if (gitOutput(clientDir,
                  {"rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"},
                  &upstream) &&
        !upstream.isEmpty()) {
        return {"pull", "--ff-only"};
    }

    QString branch;
    if (gitOutput(clientDir, {"branch", "--show-current"}, &branch) &&
        !branch.isEmpty()) {
        return {"pull", "--ff-only", "origin", branch};
    }

    return {"pull", "--ff-only", "origin", "HEAD"};
}

QString invokingNonRootUser()
{
#ifndef Q_OS_WIN
    if (geteuid() == 0) {
        const QByteArray sudoUser = qgetenv("SUDO_USER");
        if (!sudoUser.isEmpty() && sudoUser != "root")
            return QString::fromUtf8(sudoUser);
    }
#endif
    return QString();
}

QString homeForUser(const QString &user)
{
#ifndef Q_OS_WIN
    if (!user.isEmpty()) {
        if (struct passwd *pw = getpwnam(user.toLocal8Bit().constData()))
            return QString::fromLocal8Bit(pw->pw_dir);
        return QStringLiteral("/home/") + user;
    }
#endif
    return QDir::homePath();
}

QString runningClientDirUnderHome(const QString &home)
{
#ifdef Q_OS_WIN
    Q_UNUSED(home);
    return forkmesh::paths::dataRoot() +
           QStringLiteral("/src/desktop");
#else
    // The projects layout keeps the checkout in ~/projects/forkmesh/src. An
    // install made before it stays in ~/.local/share/forkmesh/src until the
    // installer next runs, so that location still answers while it exists.
    const QString modern = home + QStringLiteral("/projects/forkmesh/src/desktop");
    const QString legacy = home + QStringLiteral("/.local/share/forkmesh/src/desktop");
    return QDir(modern).exists() || !QDir(legacy).exists() ? modern : legacy;
#endif
}

