int buildJobsForMemory(qint64 totalRam, qint64 availableRam,
                              int idealThreads)
{
    constexpr qint64 gib = 1024LL * 1024 * 1024;
    // MainWindow translation units have measured peaks around 1.6 GiB; budget
    // 2 GiB each. Keep enough memory outside the build for the desktop,
    // browser, and a Node / Wrangler action; otherwise a self-update can make
    // an unrelated deploy fail while V8 is reserving its WebAssembly address
    // space. The old ceiling of four compiled the giant units four at a time
    // on a 36-core box and made every rebuild a four-to-eleven-minute wait.
    constexpr qint64 perJob = 2 * gib;
    int jobs = qBound(1, idealThreads, kMaxRebuildJobs);
    const qint64 reserve = totalRam > 0 ? qMin(6 * gib, totalRam / 2) : 6 * gib;
    if (totalRam > 0)
        jobs = qMin(jobs, qMax(1, int((totalRam - reserve) / perJob)));
    if (availableRam > 0) {
        const qint64 usable = qMax<qint64>(0, availableRam - reserve);
        jobs = qMin(jobs, qMax(1, int(usable / perJob)));
    }
    return qMax(1, jobs);
}

int ramCappedBuildJobs()
{
    return buildJobsForMemory(SystemStats::totalMemoryBytes(),
                              SystemStats::availableMemoryBytes(),
                              QThread::idealThreadCount());
}

QString buildScratchDir(const QString &buildDir)
{
    return buildDir + QStringLiteral("/.forkmesh-tmp");
}

qint64 freeBytesForPath(const QString &path)
{
    QString probe = QDir::cleanPath(path);
    while (!probe.isEmpty() && !QFileInfo::exists(probe)) {
        const QString parent = QFileInfo(probe).absolutePath();
        if (parent == probe || parent.isEmpty())
            break;
        probe = parent;
    }
    const QStorageInfo volume(probe);
    if (!volume.isValid() || !volume.isReady())
        return -1;
    return volume.bytesAvailable();
}

qint64 rebuildFreeBytesRequired(const QString &buildDir)
{
    const bool incremental =
        QFileInfo::exists(buildDir + QStringLiteral("/CMakeFiles/forkmesh.dir"));
    return incremental ? 1024LL * 1024 * 1024 : 3LL * 1024 * 1024 * 1024;
}

QString updateFailureSummary(const QString &output)
{
    if (output.contains(QLatin1String("No space left on device")))
        return QStringLiteral(
            "the disk filled up during the build. Free space on the volume "
            "holding the build directory, then start the update again — "
            "nothing was replaced.");
    const QStringList lines = output.split(QLatin1Char('\n'));
    for (const QString &line : lines) {
        const QString trimmed = line.trimmed();
        if (trimmed.contains(QLatin1String("error:")) ||
            trimmed.startsWith(QLatin1String("fatal:")))
            return trimmed.left(300);
    }
    QString tail = output.trimmed().right(300);
    const int newline = tail.indexOf(QLatin1Char('\n'));
    if (newline >= 0 && newline < tail.size() - 1)
        tail = tail.mid(newline + 1);
    return tail.trimmed();
}

QString cmakeCacheValue(const QString &cacheFile, const QString &key)
{
    QFile file(cacheFile);
    if (!file.open(QIODevice::ReadOnly | QIODevice::Text))
        return {};
    const QString prefix = key + QLatin1Char(':');
    while (!file.atEnd()) {
        const QString line = QString::fromUtf8(file.readLine()).trimmed();
        if (!line.startsWith(prefix))
            continue;
        const int equals = line.indexOf(QLatin1Char('='));
        if (equals < 0)
            return {};
        return line.mid(equals + 1);
    }
    return {};
}

QString cmakeGeneratorForRebuild()
{
    return QStandardPaths::findExecutable(QStringLiteral("ninja")).isEmpty()
               ? QString()
               : QStringLiteral("Ninja");
}

bool cmakeCacheMatches(const QString &clientDir, const QString &buildDir,
                              const QString &buildType, const QString &generator)
{
    const QString cache = buildDir + QStringLiteral("/CMakeCache.txt");
    if (!QFileInfo::exists(cache))
        return false;
    const QString cachedGenerator =
        cmakeCacheValue(cache, QStringLiteral("CMAKE_GENERATOR"));
    if (!generator.isEmpty() && cachedGenerator != generator)
        return false;
    if (cmakeCacheValue(cache, QStringLiteral("CMAKE_BUILD_TYPE")) != buildType)
        return false;
    const QString cachedSource =
        cmakeCacheValue(cache, QStringLiteral("CMAKE_HOME_DIRECTORY"));
    return !cachedSource.isEmpty() &&
           QFileInfo(cachedSource).canonicalFilePath() ==
               QFileInfo(clientDir).canonicalFilePath();
}

QStringList cmakeGeneratorEntriesToDrop(const QString &buildDir,
                                               const QString &generator)
{
    const QString cache = buildDir + QStringLiteral("/CMakeCache.txt");
    if (generator.isEmpty() || !QFileInfo::exists(cache) ||
        cmakeCacheValue(cache, QStringLiteral("CMAKE_GENERATOR")) == generator)
        return {};
    QStringList entries;
    for (const char *name : {"CMakeCache.txt", "CMakeFiles", "Makefile",
                             "cmake_install.cmake", "build.ninja",
                             ".ninja_deps", ".ninja_log"}) {
        const QString path = buildDir + QLatin1Char('/') + QLatin1String(name);
        if (QFileInfo::exists(path))
            entries << path;
    }
    return entries;
}

