QIcon agentStatusModelIcon(const AgentSession &session)
{
    if (session.model.trimmed().compare(kClaudeAutoModelId,
                                        Qt::CaseInsensitive) == 0)
        return agentControlIcon(7);
    return agentModelIcon(session.provider, session.model);
}

